from pathlib import Path
root=Path(__file__).resolve().parents[1]
html=root/'src/index.html'; s=html.read_text(encoding='utf-8')
s=s.replace('<button class="nav-item" data-page="groceries"><span>♧</span>Groceries</button>','<button class="nav-item" data-page="groceries"><span>♧</span>Groceries</button>\n        <button class="nav-item" data-page="future"><span>◇</span>Future Purchases</button>')
page='''\n      <section class="page" id="page-future">\n        <div class="stats-grid">\n          <article class="stat-card"><div class="stat-icon">◇</div><div><span>Future Total</span><strong id="future-total">$0.00</strong><small>Everything on the someday list</small></div></article>\n          <article class="stat-card"><div class="stat-icon">!</div><div><span>Needed Soon</span><strong id="future-soon-total">$0.00</strong><small>Items marked Soon</small></div></article>\n          <article class="stat-card"><div class="stat-icon">◎</div><div><span>Already Saved</span><strong id="future-saved-total">$0.00</strong><small>Money set aside for these</small></div></article>\n          <article class="stat-card highlight-card"><div class="stat-icon">$</div><div><span>Still Needed</span><strong id="future-remaining-total">$0.00</strong><small>Across all future purchases</small></div></article>\n        </div>\n        <div class="two-col">\n          <article class="panel">\n            <div class="panel-head"><div><h2>Add Future Purchase</h2><p>For things you probably are not buying right now, but know you will need eventually.</p></div></div>\n            <form class="form-grid" id="future-form">\n              <label>Item<input id="future-name" required placeholder="Winterized jeans" /></label>\n              <label>Estimated cost<input id="future-cost" type="number" min="0" step="0.01" required placeholder="60.00" /></label>\n              <label>Priority<select id="future-priority"><option value="Soon">Soon</option><option value="Eventually" selected>Eventually</option><option value="Someday">Someday</option></select></label>\n              <label>Category<select id="future-category"><option>Clothing / Gear</option><option>Home</option><option>Tech</option><option>School</option><option>Car / Transportation</option><option>Health / Personal</option><option>Other</option></select></label>\n              <label>Target date <span class="muted">(optional)</span><input id="future-date" type="date" /></label>\n              <label>Already saved <span class="muted">(optional)</span><input id="future-saved" type="number" min="0" step="0.01" value="0" /></label>\n              <label class="full">Notes <span class="muted">(optional)</span><input id="future-notes" placeholder="Need before it gets properly cold" /></label>\n              <button class="primary-btn full" type="submit">Add Future Purchase</button>\n            </form>\n          </article>\n          <article class="panel"><div class="panel-head"><div><h2>How this works</h2><p>Keep future needs visible without counting them against this paycheck yet.</p></div></div><div class="advice-box">Future Purchases do <strong>not</strong> reduce your Free Money until you move one into the current budget. You can save toward an item little by little, then promote it when you're ready to actually buy it.</div></article>\n        </div>\n        <article class="panel section-gap"><div class="panel-head"><div><h2>Future Purchase List</h2><p>Winter gear, replacement items, school stuff, tech, or anything else you know is coming later.</p></div></div><div id="future-list" class="goal-list"></div></article>\n      </section>\n\n'''
s=s.replace('      <section class="page" id="page-bills">',page+'      <section class="page" id="page-bills">')
html.write_text(s,encoding='utf-8')
js=root/'src/app.js'; s=js.read_text(encoding='utf-8')
s=s.replace('  groceryBudget: 0,','  groceryBudget: 0,\n  futurePurchases: [],')
s=s.replace('  renderGroceries();\n  renderBills();','  renderGroceries();\n  renderFuturePurchases();\n  renderBills();')
render='''function futureTotals(){let total=0,soon=0,saved=0;for(const i of state.futurePurchases){const c=Number(i.cost||0),v=Math.min(c,Number(i.saved||0));total+=c;saved+=v;if(i.priority==="Soon")soon+=Math.max(0,c-v)}return{total,soon,saved,remaining:Math.max(0,total-saved)}}\nfunction renderFuturePurchases(){const t=futureTotals();setText("future-total",money(t.total));setText("future-soon-total",money(t.soon));setText("future-saved-total",money(t.saved));setText("future-remaining-total",money(t.remaining));const el=document.getElementById("future-list");if(!el)return;const rank={Soon:0,Eventually:1,Someday:2};const items=[...state.futurePurchases].sort((a,b)=>(rank[a.priority]??9)-(rank[b.priority]??9)||(a.targetDate||"9999-12-31").localeCompare(b.targetDate||"9999-12-31")||(b.createdAt||0)-(a.createdAt||0));el.innerHTML=items.length?items.map(i=>{const c=Number(i.cost||0),sv=Math.min(c,Number(i.saved||0)),r=Math.max(0,c-sv),pct=c?Math.min(100,sv/c*100):0,when=i.targetDate?prettyDate(i.targetDate,{month:"short",day:"numeric",year:"numeric"}):"No target date";return `<div class="goal-card future-card"><div class="goal-top"><div><strong>${escapeHtml(i.name)}</strong><div class="compact-meta">${escapeHtml(i.category)} · ${escapeHtml(i.priority)} · ${when}${i.notes?` · ${escapeHtml(i.notes)}`:""}</div></div><span>${money(c)}</span></div><div class="goal-bar"><div class="goal-fill" style="width:${pct}%"></div></div><div class="goal-bottom"><span>${money(sv)} saved · ${money(r)} still needed</span><span><button class="tiny-btn" data-add-future-saving="${i.id}">Add saved money</button> <button class="tiny-btn" data-move-future="${i.id}">Move to Current Budget</button> <button class="tiny-btn danger" data-delete-future="${i.id}">Delete</button></span></div></div>`}).join(""):`<div class="empty-state">Nothing waiting for later yet. Add things like gloves, a hat, a scarf, or winterized jeans when you know you'll need them eventually.</div>`}\n\n'''
s=s.replace('function renderBills() {',render+'function renderBills() {')
s=s.replace('    groceries:["Groceries","Price the list, buy what matters now, and push the rest later."],','    groceries:["Groceries","Price the list, buy what matters now, and push the rest later."],\n    future:["Future Purchases","Keep eventual needs visible without charging them to this paycheck yet."],')
form='''  document.getElementById("future-form").addEventListener("submit",e=>{e.preventDefault();state.futurePurchases.push({id:id("future"),name:document.getElementById("future-name").value.trim(),cost:Number(document.getElementById("future-cost").value||0),priority:document.getElementById("future-priority").value,category:document.getElementById("future-category").value,targetDate:document.getElementById("future-date").value,saved:Number(document.getElementById("future-saved").value||0),notes:document.getElementById("future-notes").value.trim(),createdAt:Date.now()});e.target.reset();document.getElementById("future-priority").value="Eventually";document.getElementById("future-saved").value=0;saveState();renderAll()});\n\n'''
s=s.replace('  document.getElementById("bill-form").addEventListener("submit", e => {',form+'  document.getElementById("bill-form").addEventListener("submit", e => {')
handlers='''    else if(target.matches("[data-delete-future]"))state.futurePurchases=state.futurePurchases.filter(x=>x.id!==target.dataset.deleteFuture);\n    else if(target.matches("[data-add-future-saving]")){const x=state.futurePurchases.find(x=>x.id===target.dataset.addFutureSaving);if(x){const a=Number(prompt(`Add how much toward ${x.name}?`,"0")||0);if(a>0)x.saved=Math.min(Number(x.cost||0),Number(x.saved||0)+a)}}\n    else if(target.matches("[data-move-future]")){const x=state.futurePurchases.find(x=>x.id===target.dataset.moveFuture);if(x){const r=Math.max(0,Number(x.cost||0)-Number(x.saved||0));state.expenses.push({id:id("exp"),name:x.name,amount:r||Number(x.cost||0),category:x.category||"Other",status:"planned",date:isoDate(),notes:`Moved from Future Purchases${x.saved?` · ${money(x.saved)} already saved`:""}${x.notes?` · ${x.notes}`:""}`,createdAt:Date.now()});state.futurePurchases=state.futurePurchases.filter(i=>i.id!==x.id);showPage("budget")}}\n'''
s=s.replace('    else if (target.matches("[data-delete-bill]"))',handlers+'    else if (target.matches("[data-delete-bill]"))')
js.write_text(s,encoding='utf-8')
